package generation

import (
	"crypto/sha256"
	"fmt"
	"os"
	"strings"
)

// CompareGeneratedArtifact compares a rendered template with a checked-in
// generated file. Generation callers should render the template with the same
// config used for the build before accepting the artifact.
func CompareGeneratedArtifact(renderedPath, checkedInPath string) error {
	want, err := os.ReadFile(renderedPath)
	if err != nil {
		return fmt.Errorf("read rendered template: %w", err)
	}
	got, err := os.ReadFile(checkedInPath)
	if err != nil {
		return fmt.Errorf("read checked-in artifact: %w", err)
	}
	wantHash := sha256.Sum256(want)
	gotHash := sha256.Sum256(got)
	if wantHash != gotHash {
		return fmt.Errorf("generated artifact drift: %s differs from %s", checkedInPath, renderedPath)
	}
	return nil
}

// CompareGeneratedTemplate compares a checked-in generated shell with the
// template while ignoring the scenario-specific configuration block that the
// generator replaces. This keeps the check focused on generated behavior and
// still reports the two concrete files when the implementation drifts.
func CompareGeneratedTemplate(templatePath, checkedInPath string) error {
	template, err := os.ReadFile(templatePath)
	if err != nil {
		return fmt.Errorf("read template: %w", err)
	}
	checkedIn, err := os.ReadFile(checkedInPath)
	if err != nil {
		return fmt.Errorf("read checked-in artifact: %w", err)
	}
	normalize := func(source []byte) []byte {
		text := string(source)
		const start = "// ===== TEMPLATE CONFIGURATION - GENERATED BY SCENARIO-TO-DESKTOP ====="
		const end = "// Derived configuration"
		startIndex := strings.Index(text, start)
		endIndex := strings.Index(text, end)
		if startIndex < 0 || endIndex <= startIndex {
			return source
		}
		return []byte(text[:startIndex] + start + "\n\n" + text[endIndex:])
	}
	templateHash := sha256.Sum256(normalize(template))
	checkedInHash := sha256.Sum256(normalize(checkedIn))
	if templateHash != checkedInHash {
		return fmt.Errorf("generated artifact drift: %s differs from %s", checkedInPath, templatePath)
	}
	return nil
}
